-- =============================================================================
-- Object:      dbo.usp_Notification_Create
-- Type:        stored procedure
-- Purpose:     Inserts one notification for an employee (a NULL recipient means "any manager").
-- Parameters:  @Id uniqueidentifier - new notification id (sequential, generated by the API)
--              @Type nvarchar(30) - notification type, e.g. PinReset
--              @RecipientEmployeeId uniqueidentifier - employee who receives it, or NULL
--              @SubjectEmployeeId uniqueidentifier - employee it is about, or NULL
--              @OrderId uniqueidentifier - order it is about, or NULL
--              @SentAt datetime2 - when it was sent (UTC)
--              @Now datetime2 - current time (UTC), stored as CreatedAt and UpdatedAt
-- Returns:     nothing
-- Author:      JulianH2
-- Jira:        ITACR-36
-- =============================================================================
CREATE OR ALTER PROCEDURE dbo.usp_Notification_Create
    @Id uniqueidentifier,
    @Type nvarchar(30),
    @RecipientEmployeeId uniqueidentifier,
    @SubjectEmployeeId uniqueidentifier,
    @OrderId uniqueidentifier,
    @SentAt datetime2,
    @Now datetime2
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    INSERT INTO dbo.Notifications (Id, Type, RecipientEmployeeId, SubjectEmployeeId, OrderId, SentAt, CreatedAt, UpdatedAt)
    VALUES (@Id, @Type, @RecipientEmployeeId, @SubjectEmployeeId, @OrderId, @SentAt, @Now, @Now);
END;
